namespace OpenTPW;

/// <summary>
/// The kart and water track slice's approximation register (docs/TRACKS.md). Each entry is tagged <c>[APPROX:TRACK-NNN]</c> at its code site (a retired one leaves its BIN labels, a reclassified one an <c>[EXT:name]</c> decision, docs/TRACKS.md); the
/// words before the colon name the topic. Everything else of the slice is traced from the Mac and Windows binaries (BIN labels at the code sites).
/// </summary>
public static class TrackApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("TRACK-001", "TRACK-HEIGHT: the vehicles sample the object under each probe in the original's modes (0x450EA0: surface records, terrain + the header's +0xA0, the instance mesh) and the terrain mode reads the original's triangle sampler 0x4527F0 at the probe, as do the tile instances (0x463060: the midrange of the tile's 3 x 3 landscape vertices, 0x466D70); the surface-record mode is taken for a model with a dummy record of type bit 2 (the instance block's bit 8 the original tests is not read), faces count from either side and are baked with the full rest transforms, the instance-mesh mode reads every 0x8000 face of the model, the Halloween and space kart stations (face-sampled station models) use the straight piece's floor, and a cell with no track gives the terrain where the original samples its owner object (or keeps the previous height without one)"),
		("TRACK-002", "TRACK-HMP: the .hmp height profile is the original's per-object height map (loader 0x451640 from the mesh loader 0x4629D0, rebuilt from the mesh by 0x451880 when missing or mis-sized); the vehicles' sampler does not read it (0x4511A0 samples faces or the terrain sampler 0x4527F0, TRACK-001) and neither do OpenTPW's vehicles; the kit parses it; the readers of the object's map (+0xCC) are the cell-height lookup 0x452AE0 (the cell owner's map byte x 100/255 plus its base height, else the landscape; callers 0x45CDC0, 0x532FC0, 0x536CA0, 0x5370E0 and the tour code 0x55ABF0, 0x55C350, 0x55CC00, TOUR-005), the instance bounding box 0x466B70 (the map's +0x1C/+0x28 extremes plus the instance height; callers 0x556AF0, 0x556B90, 0x556DE0, 0x5587F0, 0x559060, 0x5597A0, 0x55A100), the ride preview 0x4689F0 (0x486410 from 0x4AB1B0) and the cell-flag copy of the mesh creation 0x463060 (bit 0x80 cells of the map written into the landscape cells; every shipped map's flags are zero), none of which belongs to the kart or water vehicles; what those readers decide in OpenTPW's tour, ghost and bounding-box code is not traced"),
		("TRACK-004", "TRACK-X2LINK: the flow links of water crossings and tees are written as the original's line op does (0x539670: a tile with more than two arms ORs the line's direction into +0xD, so crossings get 0x14, 0x41, 0x50 or 0x05; the circuit walk 0x52A970 writes +0xD only at corners); not modelled: the clear op (ClearCell 0x53B280 -> 0x5227F0) removes the direction bits of a cleared line from a junction's link where OpenTPW removes the tile or counts the overlap down, and the other writers of +0xD (the type-25 walk 0x52BA50 takes the first linked arm by rotation, the edit sub-modes 0x52B400) have no counterpart"),
		("TRACK-005", "TRACK-STATION: the station is the original's line of 0x52A1A0 from the attraction cell (the anchor): two tiles of type 13 or 18 on the footprint's rows 1 and 2 across the heading, the circuit starting at the first, the controller reference between the tiles (0x529E10, 0x545890) and the piece walks 0x52A490 and 0x52A700 starting where it does; the line modes 0x80 and 0x83 of 0x53AAC0 (0x82 is the flow link, TRACK-004) and what they write on the station tiles are not traced"),
		("TRACK-007", "TRACK-DEMOLISH: removing a kart or water ride refunds the track cell cost x the ride's scrap percentage / 100 per tile laid for it (ClearCell 0x53B280 credits it at 0x53B622 for a cleared type 11 or 16 tile; the replay runs with flag 0x81B46C = 1, so no end tile is skipped) and then charges 2 x the cell cost x the scrap percentage / 100 once (0x4D01F0, 0x528157..0x528179), both only for a type with Info.HasQueue (def+0x40) as the original; approximated: the original clears and refunds only what its two walks from the station reach (0x530830 forward and 0x530B70 backward record the circuit's corner points, at most 0x401, and 0x52FE50 replays the lines between them, a tile written again refunding on its last clearing visit), so a tile laid for the ride but cut off from its station stays and refunds nothing there, where OpenTPW removes and refunds every tile the ride owns"),
		("TRACK-008", "TRACK-ADDON: the add-on flag 0x10 is stamped by the placement and read into the kind 12 and 13 sections (TrackBuilder.CanStandAddOn, ParkCellMap.WriteFootprint, Level.PlaceAddOn: a headless API, as the build panel does not offer add-ons); not built: the sections' run counters and values (+8 the place in the run of add-on tiles, +0xC the add-on's instance, +0x10 its type id, 0x52ac68), the show and hide of the add-on's class-1 dummies 1 and 0x10, the Space Racers Teleport's vehicle hook (0x548ca5 -> 0x548e80), the walk after an add-on's placement, and where the original offers and sells a ride's add-ons (the object window code 0x481bc0..0x486d90 reads an add-on's ride through 0x4e2710)"),
		("TRACK-010", "TRACK-BRIDGE: a kart or water tile with at most two arms and no corner (straights, single-arm ends, armless tiles, 0x538AA4..0x538B05) is a bridge when it replaced path cells; the original tests the map layer under the track (a path or queue under any of its four cells, kept there and re-tested when a path is laid later) and only type 25 tests map types 2, 7 and 30 (cells outside the park); OpenTPW's track replaces the paths, so it remembers them when the tile is laid, writes no type 25, and takes the ahead and behind neighbours of the second pass from the flow link (an end or armless tile without a link along it takes the positive axis), whose PC twin is not traced"),
		("TRACK-014", "TRACK-WALK: the circuit walk is the original's 0x52A970 (heading kept on every non-corner cell, corners take mask ^ opposite and rewrite +0xD, 0-based steps to +0x24, failure on a non-track cell, fewer than two arms, a three-arm cell with type 0 or an armless track cell two ahead while the heading has bit 0x01, arrival at the start from any side, writes in both modes); not modelled: the readers of the step number +0x24 (the getter 0x53AEC0 at 0x53AEE6), all of which belong to the track tool's edit sub-modes 0xE and 0x13 (TRACK-018: 0x524960 orders its two clicked tiles by step before its calls of 0x52B400 at 0x526372 and 0x526B5E, 0x52B400 finds the tiles of the cut by equal steps and 0x527960, run by the hover 0x5234D0, picks the tile under the pointer), so the 0-based step and the side-entry arrival feed nothing here; the walk's step limit is OpenTPW's ([EXT:track-walk-step-limit])"),
		("TRACK-018", "TRACK-ANIM: the pieces' arm masks and their m clips play as the original triggers them (BUMP 17, the placement and line walks), and the renderer draws texture-coordinate clips only, which is all the shipped pieces need (the Crypt Karts' bridge clips gk_trckH*m carry one texture-frame track on the one-frame slot 0 whose 20 keys all name frame 0, the bind the piece already has, and no member of the archive animates the flame slot), but the track tool's edit sub-modes 0xE and 0x13 have no counterpart: on a closed circuit (the ride's word +0x2C that the walk 0x52A970 sets) two clicks on its tiles are ordered by their step numbers (+0x24, 0x53AEC0) and cut the track between them (0x52B400 after the pick tests 0x539760: the tile clears 0x53B280 and the re-links of the cut's end tiles 0x53BC60), then the walk (0x526BD0) starts the pieces from the cut on a valid circuit (0x52A490 forward) or stops them (0x52A490 and 0x52A700) on an invalid one, and the tool goes on as the line tool 0xB or 0x10 from the track's open end (0x530830); OpenTPW's track tool (b_track) lays a line from the station's exit on every entry, with no cut and no continuation at the open end"),
		("TRACK-026", "TRACK-HEADS: a kart's riders are drawn as head sprites at the head dummies (class 0x100000B1, numbers 1 and 2) through the ride-head renderer in the original's seat order (rider list order, 0x549C60); 0x0044B410 is the PC twin of ADDHEAD (it marks the head record 0x14 bytes apart and has 0x00475A10 create the head thing, type 1 or 3 for a costume head; its callers are the seat code 0x549C60, 0x43B600, 0x548E80, 0x557D80 and 0x55D830), whose sprite the shared thing renderer draws (the sizes belong to the HEADS entries); the boarding guest between BUMP 1 and the car's creation is not traced"),
		("TRACK-032", "SAVED-RIDE CONTROLLER: a saved kart or water ride's controller is rebuilt from the saved circuit (BumpController.RestoreCircuit after a re-walk), where tp.exe's loader 0x543560 (called from 0x415270) restores the controller from the save stream and the ride's controller handle +0x28 then points at it; the stream's record layout, and whether the walk verdict is re-derived on load, are not traced (evidence needed: the record layout read by 0x543560)"),
	};
}
